// Normalise and validate incoming form data (works with JSON or form-encoded posts)
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const name = String(b.name ?? '').trim();
  const email = String(b.email ?? '').trim().toLowerCase();
  const message = String(b.message ?? '').trim();
  const errors = [];
  if (!name) errors.push('name is missing');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) errors.push('email looks invalid');
  if (message.length > 5000) errors.push('message is too long');
  out.push({ json: {
    received_at: new Date().toISOString(),
    name, email,
    phone: String(b.phone ?? '').trim(),
    message,
    source: String(b.source ?? 'website form'),
    valid: errors.length === 0,
    errors: errors.join('; '),
  }});
}
return out;
